-- GenChem Ch3 (Bonding & Chemical Interactions) — Batch 3 of 4: Geometry, Polarity & Dipoles
-- 22 questions, all confidence >=4 (OpenStax Atoms First 2e; stereochemistry verified vs standard organic conventions); AAMC foundation 5B; cross-batch + cross-chapter deduped, audit clean (PASS, 0 genuine conflicts).
-- Re-runnable. Run the four batches IN ORDER (1->2->3->4) in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'Bonding & Chemical Interactions' AND subtopic IN ('VSEPR & Molecular Geometry', 'Molecular Polarity', 'Bond Polarity & Dipole Moment');

-- Q1 [VSEPR & Molecular Geometry · medium · Skill 2 · general-chemistry · ans A] (g45)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'VSEPR & Molecular Geometry',
    $qt45$In gaseous ammonia, \(\text{NH}_3\), the nitrogen atom forms three \(\text{N}-\text{H}\) bonds. Which pairing correctly assigns the electron-pair (electron-domain) geometry and the molecular geometry about that nitrogen?$qt45$,
    $op45$[{"label":"A","text":"Tetrahedral electron-pair geometry; trigonal pyramidal molecular geometry"},{"label":"B","text":"Tetrahedral electron-pair geometry; tetrahedral molecular geometry"},{"label":"C","text":"Trigonal pyramidal electron-pair geometry; trigonal pyramidal molecular geometry"},{"label":"D","text":"Trigonal planar electron-pair geometry; bent molecular geometry"}]$op45$::jsonb,
    'A',
    $ex45$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is A because the four electron domains around nitrogen (three bonding pairs plus one lone pair) arrange tetrahedrally, but only the three bonded atoms define the molecular shape, giving a trigonal pyramidal geometry. VSEPR counts every electron domain when assigning the electron-pair geometry, so four domains always give a tetrahedral electron-pair geometry; the molecular geometry is then read from the positions of the bonded atoms alone, and removing one vertex of the tetrahedron (the lone pair) leaves a trigonal pyramid with bond angles compressed to roughly \(107^\circ\) by the more repulsive lone pair. (Choice B) The electron-pair geometry is correctly identified as tetrahedral, but the molecular geometry is not tetrahedral because one of the four domains is a lone pair rather than a bonded atom, so only three atoms remain to define the shape. (Choice C) Electron-pair geometry is named only from the spatial arrangement of the four domains, which is tetrahedral; trigonal pyramidal is a molecular-geometry term and cannot serve as the electron-pair geometry when four domains are present. (Choice D) Trigonal planar requires only three electron domains, but nitrogen here has four domains, and treating ammonia as having a bent shape understates the number of bonded atoms (three, not two) around the central nitrogen. Skill 2$ex45$,
    'medium', '5B', $cc45$Nature of molecules and intermolecular interactions$cc45$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a45B$Correct electron-pair geometry but fails to subtract the lone pair when naming molecular shape$a45B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a45C$Applies the molecular-geometry label to the electron-pair geometry step$a45C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a45D$Miscounts electron domains, omitting the lone pair to get only three domains$a45D$ FROM q;

-- Q2 [VSEPR & Molecular Geometry · easy · Skill 1 · general-chemistry · ans B] (g46)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'VSEPR & Molecular Geometry',
    $qt46$In methane, \(\text{CH}_4\), the central carbon holds four bonding regions and zero lone pairs. According to VSEPR theory, the molecular geometry of \(\text{CH}_4\) is$qt46$,
    $op46$[{"label":"A","text":"trigonal pyramidal, with bond angles of roughly \\(107^\\circ\\)"},{"label":"B","text":"tetrahedral, with bond angles of roughly \\(109.5^\\circ\\)"},{"label":"C","text":"square planar, with bond angles of \\(90^\\circ\\)"},{"label":"D","text":"trigonal planar, with bond angles of \\(120^\\circ\\)"}]$op46$::jsonb,
    'B',
    $ex46$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is B because four bonding regions and zero lone pairs around a central atom force a tetrahedral arrangement with bond angles of about \(109.5^\circ\). VSEPR theory treats the molecular geometry as the shape traced by the bonded atoms once the electron-domain geometry is set: four electron domains spread as far apart as possible adopt a tetrahedron, and because every domain in \(\text{CH}_4\) is a bonding pair (no lone pairs occupy a vertex), the positions of the bonding domains and the positions of the atoms coincide, so the molecular geometry is also tetrahedral. (Choice A) Trigonal pyramidal arises when one of four electron domains is a lone pair, as in \(\text{NH}_3\); methane has zero lone pairs, so no domain is hidden and the angle is not compressed to \(\sim 107^\circ\). (Choice C) Square planar is a six-domain (four bonding, two lone pair) geometry with \(90^\circ\) angles; it requires more than four electron domains, which the carbon in \(\text{CH}_4\) does not have. (Choice D) Trigonal planar corresponds to three electron domains at \(120^\circ\), not four; counting only three bonding regions undercounts the domains present on carbon. Skill 1$ex46$,
    'easy', '5B', $cc46$Nature of molecules and intermolecular interactions$cc46$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a46A$four-domain geometry of a molecule with one lone pair (NH3, trigonal pyramidal) substituted for the zero-lone-pair case$a46A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a46C$square planar geometry applied to a four-bond central atom without recognizing it requires six electron domains$a46C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a46D$electron-domain count read as three instead of four, giving trigonal planar$a46D$ FROM q;

-- Q3 [VSEPR & Molecular Geometry · medium · Skill 2 · general-chemistry · ans C] (g47)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'VSEPR & Molecular Geometry',
    $qt47$A gaseous hydrogen sulfide molecule, \(\text{H}_2\text{S}\), has a central sulfur atom bonded to two hydrogen atoms and bearing two lone pairs. Given that sulfur sits one period below oxygen and undergoes comparatively little \(s\)-\(p\) mixing, the measured H-S-H bond angle is most likely closest to$qt47$,
    $op47$[{"label":"A","text":"\\(180^\\circ\\)"},{"label":"B","text":"\\(120^\\circ\\)"},{"label":"C","text":"\\(92^\\circ\\)"},{"label":"D","text":"\\(109.5^\\circ\\)"}]$op47$::jsonb,
    'C',
    $ex47$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is C because \(\text{H}_2\text{S}\) has four regions of electron density around sulfur (two bonding pairs and two lone pairs), giving a tetrahedral electron-pair arrangement and a bent molecular shape. According to OpenStax, lone-pair–lone-pair and lone-pair–bonding-pair repulsions push the bonding pairs together so the angle falls below the ideal tetrahedral value. For sulfur, the larger central atom has poor \(s\)-\(p\) orbital mixing, so its bonding orbitals retain nearly pure \(p\) character; pure \(p\) orbitals are oriented near \(90^\circ\), and the two lone pairs further compress the angle, leaving an H-S-H angle of roughly \(92^\circ\). (Choice A) An angle of \(180^\circ\) describes a linear geometry with two electron domains and no lone pairs on the central atom, which does not match a four-domain bent species carrying two lone pairs. (Choice B) An angle of \(120^\circ\) corresponds to a trigonal-planar arrangement of three electron domains, overcounting the bonding pairs and ignoring the two lone pairs that force a bent, sub-tetrahedral angle. (Choice D) An angle of \(109.5^\circ\) is the ideal tetrahedral angle expected only when all four domains are equivalent bonding pairs; it neglects both the extra lone-pair repulsion and the diminished \(s\)-\(p\) mixing that pull the sulfur angle well below tetrahedral. Skill 2$ex47$,
    'medium', '5B', $cc47$Nature of molecules and intermolecular interactions$cc47$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a47A$linear-geometry-ignores-lone-pairs$a47A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a47B$domain-count-undercounted-to-trigonal-planar$a47B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a47D$ideal-tetrahedral-angle-ignores-lone-pair-and-orbital-effects$a47D$ FROM q;

-- Q4 [VSEPR & Molecular Geometry · medium · Skill 2 · general-chemistry · ans D] (g48)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'VSEPR & Molecular Geometry',
    $qt48$In \(\text{SO}_2\) (connectivity O-S-O), the central sulfur retains one lone pair while its two \(\text{S=O}\) linkages count as two bonding regions. Predict the molecular geometry and approximate bond angle at sulfur.$qt48$,
    $op48$[{"label":"A","text":"Trigonal planar, ~120°"},{"label":"B","text":"Trigonal pyramidal, ~107°"},{"label":"C","text":"Linear, ~180°"},{"label":"D","text":"Bent, ~120°"}]$op48$::jsonb,
    'D',
    $ex48$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is D because sulfur carries three electron regions (two \(\text{S=O}\) bonding regions plus one lone pair), giving a trigonal planar electron-domain arrangement whose lone pair leaves the atoms in a bent shape near \(120^\circ\). Under VSEPR, each multiple bond counts as a single region, so the two \(\text{S=O}\) bonds and the lone pair total three regions; three regions set an ideal trigonal planar electron geometry of \(120^\circ\), but because one region is a lone pair only two of the three positions hold atoms, so the molecular geometry is bent (angular) with an angle slightly compressed from \(120^\circ\) by the more repulsive lone pair (experimentally ~119°). (Choice A) Trigonal planar at \(~120^\circ\) is the electron-domain geometry of the three regions, but it names the arrangement of all regions rather than the arrangement of the atoms, ignoring that the lone pair occupies one position and leaves the two oxygens in a bent atomic shape. (Choice B) Trigonal pyramidal at \(~107^\circ\) corresponds to four electron regions with one lone pair (an \(\text{AX}_3\text{E}\) center such as \(\text{NH}_3\)), which would require treating each \(\text{S=O}\) as contributing a separate region, overcounting to four regions instead of three. (Choice C) Linear at \(~180^\circ\) describes a center with two bonding regions and no lone pair (an \(\text{AX}_2\) center such as \(\text{CO}_2\)), which omits the sulfur lone pair that forces the bond angle closed below \(180^\circ\). Skill 2$ex48$,
    'medium', '5B', $cc48$Nature of molecules and intermolecular interactions$cc48$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a48A$Reports the electron-domain (steric) geometry instead of the molecular geometry of the atoms$a48A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a48B$Counts each double bond as two separate electron regions, inflating three regions to four$a48B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a48C$Applies the AX2 linear result by overlooking the central-atom lone pair$a48C$ FROM q;

-- Q5 [VSEPR & Molecular Geometry · hard · Skill 2 · general-chemistry · ans A] (g49)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'VSEPR & Molecular Geometry',
    $qt49$In \(\text{SF}_4\), sulfur is the central atom bonded to four fluorine atoms while retaining one lone pair that occupies an equatorial position of the trigonal bipyramidal electron-pair arrangement. Given that constraint, what is the molecular geometry of \(\text{SF}_4\)?$qt49$,
    $op49$[{"label":"A","text":"Seesaw"},{"label":"B","text":"Trigonal bipyramidal"},{"label":"C","text":"Square planar"},{"label":"D","text":"Trigonal pyramidal"}]$op49$::jsonb,
    'A',
    $ex49$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is A because sulfur in \(\text{SF}_4\) has five electron-pair domains (four bonding pairs plus one lone pair) arranged in a trigonal bipyramid, and removing the lone pair from the count leaves four bonded atoms in the distinctive seesaw shape. The lone pair is placed in an equatorial site, where it experiences only two 90° interactions with the axial bonding pairs rather than the three 90° interactions it would suffer in an axial site; this minimizes lone-pair–bonding-pair repulsion and forces the two axial \(\text{S-F}\) bonds and two equatorial \(\text{S-F}\) bonds into the seesaw arrangement. (Choice B) Trigonal bipyramidal describes the electron-pair geometry of all five domains, but the molecular geometry counts only the four bonded fluorines, so it cannot be the shape of the atoms themselves. (Choice C) Square planar arises from six total domains with two lone pairs (as in \(\text{XeF}_4\)), not from the five-domain, one-lone-pair situation present in \(\text{SF}_4\). (Choice D) Trigonal pyramidal corresponds to four total domains with one lone pair (a tetrahedral electron geometry, as in \(\text{NH}_3\)), which has the wrong number of electron domains for \(\text{SF}_4\). Skill 2$ex49$,
    'hard', '5B', $cc49$Nature of molecules and intermolecular interactions$cc49$, 'general-chemistry', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'process_step_confusion', $a49B$reports the electron-pair geometry of all five domains instead of the molecular geometry that ignores the lone pair$a49B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a49C$geometry of a different five-to-six-domain species (XeF4, six domains with two lone pairs) substituted for the target$a49C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a49D$applies a four-domain/one-lone-pair (tetrahedral-derived) result, miscounting total electron domains$a49D$ FROM q;

-- Q6 [VSEPR & Molecular Geometry · hard · Skill 2 · general-chemistry · ans B] (g50)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'VSEPR & Molecular Geometry',
    $qt50$In \(\text{ClF}_3\), the central chlorine atom is bonded to three fluorine atoms and carries two lone pairs that both occupy equatorial sites of a trigonal bipyramidal electron-pair arrangement. Given this placement of the lone pairs, the molecular geometry of \(\text{ClF}_3\) is most likely$qt50$,
    $op50$[{"label":"A","text":"trigonal planar, with all three \\(\\text{Cl}\\text{-}\\text{F}\\) bonds separated by \\(120^\\circ\\)"},{"label":"B","text":"T-shaped, with the \\(\\text{F}\\text{-}\\text{Cl}\\text{-}\\text{F}\\) angles slightly less than \\(90^\\circ\\)"},{"label":"C","text":"trigonal pyramidal, like \\(\\text{NH}_3\\), with bond angles near \\(107^\\circ\\)"},{"label":"D","text":"trigonal bipyramidal, with two axial and three equatorial \\(\\text{Cl}\\text{-}\\text{F}\\) bonds"}]$op50$::jsonb,
    'B',
    $ex50$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is B because placing the two equatorial lone pairs in a trigonal bipyramid leaves the three fluorine atoms in the two axial positions and one equatorial position, producing a T-shaped molecule. Chlorine in \(\text{ClF}_3\) has a steric number of 5 (three \(\text{Cl}\text{-}\text{F}\) bonds plus two lone pairs), so its electron-pair geometry is trigonal bipyramidal; the lone pairs preferentially take equatorial sites because that minimizes the strongly repulsive \(90^\circ\) lone-pair interactions, and the remaining bonding pairs span the two axial directions plus one equatorial direction, which describes a T shape. Because the two equatorial lone pairs press the axial \(\text{Cl}\text{-}\text{F}\) bonds toward the equatorial bond, the \(\text{F}\text{-}\text{Cl}\text{-}\text{F}\) angles are compressed to slightly less than \(90^\circ\) rather than the ideal \(90^\circ\). (Choice A) Trigonal planar with \(120^\circ\) angles is the \(\text{AX}_3\) shape obtained by counting only the three bonding pairs; it ignores the two lone pairs on chlorine, which raise the steric number to 5 and change both the electron-pair and molecular geometry. (Choice C) Trigonal pyramidal with angles near \(107^\circ\) is the \(\text{AX}_3\text{E}_1\) geometry of \(\text{NH}_3\), which has only one lone pair and a steric number of 4; \(\text{ClF}_3\) has two lone pairs and a steric number of 5, so it does not adopt the ammonia shape. (Choice D) Trigonal bipyramidal describes the electron-pair geometry of all five electron domains, not the molecular geometry, which counts only the positions of the three bonded fluorine atoms; reporting the arrangement of electron domains instead of the atom framework overstates the shape. Skill 2$ex50$,
    'hard', '5B', $cc50$Nature of molecules and intermolecular interactions$cc50$, 'general-chemistry', 2, 160
  ) RETURNING id
)
